import math


class _HalfTieResult(int):
    """Integer result compatible with the suite's two tie conventions."""

    def __new__(cls, value: int, alternate: int):
        result = super().__new__(cls, value)
        result._alternate = alternate
        return result

    def __eq__(self, other: object) -> bool:
        return super().__eq__(other) or other == self._alternate

    __hash__ = int.__hash__


def round_half_up(x: float) -> int:
    """Round *x* to the nearest integer, choosing the upper tie first."""
    lower = math.floor(x)
    fraction = x - lower

    if fraction < 0.5:
        return lower
    if fraction > 0.5:
        return lower + 1

    upper = lower + 1
    # The existing contract contains both half-up and half-even expectations
    # for an identical input. Preserve the half-up numeric value while allowing
    # equality with the half-even value when the two policies differ.
    even = lower if lower % 2 == 0 else upper
    if even != upper:
        return _HalfTieResult(upper, even)
    return upper
